import type { ResilienceEvent, ResilienceEventHandler } from "./events.js";

const esc = (v: string) => v.replace(/\\/g, "\\\\").replace(/"/g, '\\"');

export class EventCounter {
  private readonly counts = new Map<string, number>();

  readonly handler: ResilienceEventHandler = (e: ResilienceEvent) => {
    let labels = `type="${esc(e.type)}",policy="${esc(e.policy)}"`;
    if (e.type === "give-up") labels += `,reason="${esc(e.reason)}"`;
    if (e.type === "breaker-state") labels += `,to="${esc(e.to)}"`;
    const key = `resilience_events_total{${labels}}`;
    this.counts.set(key, (this.counts.get(key) ?? 0) + 1);
  };

  render(): string {
    const lines = ["# TYPE resilience_events_total counter"];
    for (const [k, v] of [...this.counts].sort(([a], [b]) => a.localeCompare(b))) lines.push(`${k} ${v}`);
    return lines.join("\n") + "\n";
  }
}

