import { NEVER, type Operation, type Policy } from "./types.js"; // the ONE shared NEVER: a local copy would make inner timeouts listen on it again (F1)

export interface FallbackOptions<F> {
  value: (error: unknown) => F | Promise<F>;
  shouldFallback?: (error: unknown) => boolean; // default: every error
}

export class FallbackPolicy<F> implements Policy {
  constructor(private readonly options: FallbackOptions<F>) {}

  async execute<T>(operation: Operation<T>, signal?: AbortSignal): Promise<T> {
    signal?.throwIfAborted();
    try {
      return await operation(signal ?? NEVER);
    } catch (error) {
      if (signal?.aborted) throw signal.reason; // the caller is gone: nobody wants a fallback
      if (this.options.shouldFallback !== undefined && !this.options.shouldFallback(error)) throw error;
      return (await this.options.value(error)) as unknown as T; // Policy is generic per call: caller keeps T == F
    }
  }
}

// test/fallback.test.ts
import { describe, expect, it } from "vitest";
import { CircuitBreaker } from "../src/breaker.js";
import { FallbackPolicy } from "../src/fallback.js";
import { isRetryableHttp } from "../src/http.js";
import { RetryPolicy } from "../src/retry.js";
import { wrap } from "../src/wrap.js";

describe("FallbackPolicy", () => {
  it("answers after retries give up, and on an open breaker without calling the operation", async () => {
    const breaker = new CircuitBreaker({ windowSize: 2, minimumCalls: 2 });
    const policy = wrap(
      new FallbackPolicy({ value: () => "cached" }),
      new RetryPolicy({ maxAttempts: 2, sleep: async () => {}, shouldRetry: isRetryableHttp }),
      breaker,
    );
    let calls = 0;
    const down = async () => { calls++; throw new Error("down"); };
    expect(await policy.execute(down)).toBe("cached");
    expect(calls).toBe(2);
    expect(breaker.state).toBe("open");
    expect(await policy.execute(down)).toBe("cached");
    expect(calls).toBe(2); // open breaker: the operation was not called
  });

  it("does not fall back when the caller aborted", async () => {
    const caller = new AbortController();
    caller.abort(new Error("client gone"));
    await expect(new FallbackPolicy({ value: () => "x" }).execute(async () => 1, caller.signal)).rejects.toThrow("client gone");
  });

  it("rethrows errors shouldFallback rejects", async () => {
    const p = new FallbackPolicy({ value: () => "x", shouldFallback: (e) => !(e instanceof TypeError) });
    await expect(p.execute(async () => { throw new TypeError("bad input"); })).rejects.toThrow("bad input");
  });
});

