export function recommended(p: { retry?: Policy; breaker?: Policy; bulkhead?: Policy; timeout?: Policy }): Policy {
  const ordered = [p.retry, p.breaker, p.bulkhead, p.timeout].filter((x): x is Policy => x !== undefined);
